const fs = require('fs');

async function testNativeImport() {
  const loginRes = await fetch('https://fleet.uptoware.com/api/method/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ usr: 'Administrator', pwd: 'admin' })
  });
  const cookie = loginRes.headers.get('set-cookie');
  console.log('Logged in successfully.');

  const plate = 'KA-34-IMP-' + Math.floor(1000 + Math.random() * 9000);
  console.log(`Generating test vehicle: ${plate}`);

  // Use the exact CSV headers generated by download_template for Vehicle
  const headers = '"License Plate","Make","Model","Vehicle Type","Transport Type","Vehicle Status","Operational Mine Site","Odometer Value (Last)","Fuel Type","Fuel UOM"';
  const row = `"${plate}","Tata","Prima 3538.K","Tipper","Transport","Active","JBR Eastern — Talcher Site",15000,"Diesel","Litre"`;
  const csvContent = `${headers}\n${row}\n`;

  const blob = new Blob([csvContent], { type: 'text/csv' });
  const formData = new FormData();
  formData.append('file', blob, 'test_vehicle_import.csv');
  formData.append('doctype', 'Vehicle');

  console.log('Uploading file to /api/import/upload...');
  const uploadRes = await fetch('https://fleet.uptoware.com/api/import/upload', {
    method: 'POST',
    headers: {
      'Cookie': cookie,
      'Origin': 'https://fleet.uptoware.com'
    },
    body: formData
  });

  const uploadJson = await uploadRes.json();
  console.log('Upload Status:', uploadRes.status);
  console.log('Upload Response:', JSON.stringify(uploadJson, null, 2));

  if (uploadJson.success && uploadJson.dataImportId) {
    console.log(`Polling status for ${uploadJson.dataImportId}...`);
    for (let i = 0; i < 5; i++) {
      await new Promise(r => setTimeout(r, 2000));
      const statusRes = await fetch(`https://fleet.uptoware.com/api/import/status?id=${encodeURIComponent(uploadJson.dataImportId)}`, {
        headers: { 'Cookie': cookie }
      });
      const statusJson = await statusRes.json();
      console.log(`Poll ${i + 1}: status = ${statusJson.status}, success = ${statusJson.successCount}, failed = ${statusJson.failedCount}`);
      if (['Success', 'Partial Success', 'Error'].includes(statusJson.status)) {
        console.log('Final Result Logs:', JSON.stringify(statusJson.logs, null, 2));
        break;
      }
    }

    // Verify record in ERPNext database
    const vCheck = await fetch(`https://fleet.uptoware.com/api/vehicles`, {
      headers: { 'Cookie': cookie }
    });
    const vJson = await vCheck.json();
    const created = vJson.vehicles?.find(v => v.licensePlate === plate || v.id === plate);
    if (created) {
      console.log(`🎉 VERIFIED: Vehicle ${plate} found in ERPNext database!`);
    } else {
      console.log(`Notice: Vehicle ${plate} not found in first page of vehicles.`);
    }
  }
}

testNativeImport().catch(console.error);
